   Action<string> switchFrame=label=>UI.Descendants<Button>(Find<StackPanel>("InspectorNavigationItems")).Single(b=>b.Content is StackPanel&&((StackPanel)b.Content).Children.OfType<TextBlock>().Any(t=>t.Text==label)).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));switchFrame("背景");await Task.Delay(100);string originalColor=Doc.Style.ColorA;var color=UI.Descendants<TextBox>(inspector).Single(b=>(string)b.Tag=="color:颜色");color.Text="invalid";color.RaiseEvent(new KeyboardFocusChangedEventArgs(Keyboard.PrimaryDevice,0,color,null){RoutedEvent=Keyboard.LostKeyboardFocusEvent});if(Doc.Style.ColorA!=originalColor||color.Text=="invalid")throw new Exception("Invalid color not restored");color.Text="#8fd";color.RaiseEvent(new KeyboardFocusChangedEventArgs(Keyboard.PrimaryDevice,0,color,null){RoutedEvent=Keyboard.LostKeyboardFocusEvent});if(Doc.Style.ColorA!="#88FFDD")throw new Exception("Short hex color did not apply");History(false);if(Doc.Style.ColorA!=originalColor)throw new Exception("Color input undo failed");switchFrame("布局");await Task.Delay(100);if(Math.Abs(scroll.VerticalOffset-savedOffset)>1)throw new Exception("Inspector scroll position not restored");
